'use strict';
let mapProvider=0,observedMap=null,swipeMap=null,swipeOwner=null,swipeSync=null,htmlMarkers=[];
const primaryStyle='https://tiles.openfreemap.org/styles/liberty';
const fallbackStyle={version:8,sources:{osm:{type:'raster',tiles:['https://tile.openstreetmap.org/{z}/{x}/{y}.png'],tileSize:256,maxzoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}},layers:[{id:'osm',type:'raster',source:'osm'}]};
const originalFallback=fallbackMap,originalGeo=renderGeo,originalMarkers=geoMarkers,originalRenderer=rendererMode;
fallbackMap=function(reason){clearTimeout(geoTimer);if(!offlineMode&&navigator.onLine&&window.maplibregl&&mapProvider===0&&!/WebGL|library/.test(reason)){mapProvider=1;window.DABasemapStyle=fallbackStyle;if(geoMap)geoMap.remove();geoMap=null;geoReady=false;geoArea=null;observedMap=null;closeSwipe();if($('map-status'))$('map-status').textContent='Primary tiles unavailable · trying OpenStreetMap raster';renderGeo(true);return;}if($('map-status'))$('map-status').textContent=offlineMode?'Offline rehearsal on · bundled schematic':navigator.onLine?'Tiles blocked/unavailable · schematic fallback':'Network offline · bundled schematic';closeSwipe();originalFallback(offlineMode?'Offline rehearsal on.':reason);};
rendererMode=function(mode){if(mode==='geo'&&renderer!=='geo'){mapProvider=0;window.DABasemapStyle=primaryStyle;}if(mode==='svg')closeSwipe();originalRenderer(mode);};
geoMarkers=function(){const collection=originalMarkers();for(const f of collection.features){const b=state.data.barriers.find(b=>b.id===f.properties.id),o=state.data.surveyObservations?.find(o=>o.id===b?.observationId);if(o?.link?.coordinate)f.geometry.coordinates=o.link.coordinate;}return collection;};
function surveyFeatures(){return{type:'FeatureCollection',features:(state.data.surveyObservations||[]).filter(o=>Number.isFinite(o.lat)&&Number.isFinite(o.lon)).map(o=>({type:'Feature',geometry:{type:'Point',coordinates:[o.lon,o.lat]},properties:{id:o.id,status:o.link.status,positive:DASurvey.positive(o.type),fixture:!!o.fixture}}))};}
function inspectObservation(id){$('advanced').open=true;switchTab('import');renderSurvey();const form=[...$('survey-list').querySelectorAll('form')].find(f=>f.dataset.observation===id);if(form){form.closest('details').open=true;form.scrollIntoView({block:'center'});}}
renderGeo=function(fit=false){originalGeo(fit);if(!geoMap||!geoReady)return;if(observedMap!==geoMap){observedMap=geoMap;const map=geoMap;map.addSource('da-survey',{type:'geojson',data:surveyFeatures()});map.addLayer({id:'da-survey',type:'circle',source:'da-survey',paint:{'circle-radius':6,'circle-color':['case',['==',['get','status'],'linked'],['case',['get','positive'],'#67e4ca','#ff8297'],'#f6cc70'],'circle-stroke-width':2,'circle-stroke-color':'#102331'}});map.on('click','da-survey',e=>inspectObservation(e.features[0].properties.id));map.on('idle',()=>{if(renderer==='geo'&&geoMap===map&&$('map-status'))$('map-status').textContent=mapProvider?'OpenStreetMap raster basemap':'OpenFreeMap basemap';});}
 geoMap.getSource('da-survey')?.setData(surveyFeatures());for(const marker of htmlMarkers)marker.remove();htmlMarkers=[];if(geoMap.getLayer('da-mark-label'))geoMap.removeLayer('da-mark-label');for(const f of geoMarkers().features){const button=document.createElement('button'),b=state.data.barriers.find(b=>b.id===f.properties.id);button.className='geo-barrier'+(f.properties.resolved?' repaired':'');button.textContent=f.properties.resolved?'✓':'×';button.setAttribute('aria-label','Inspect '+b.title+' · '+b.provenance);button.onclick=e=>{e.stopPropagation();inspectBarrier(b.id);};htmlMarkers.push(new maplibregl.Marker({element:button}).setLngLat(f.geometry.coordinates).addTo(geoMap));}if(typeof swipeEnabled!=='undefined'&&swipeEnabled)renderSwipe();};
function stopSwipeAnimation(){} // Animation state is revision-guarded in applyPlan; no independent timer survives cancellation.
function closeSwipe(){if(swipeOwner&&swipeSync)swipeOwner.off('move',swipeSync);swipeSync=null;swipeOwner=null;if(swipeMap){swipeMap.remove();swipeMap=null;}$('before-map')?.remove();$('swipe-control')?.remove();}
function renderSwipe(){if(!swipeEnabled||renderer!=='geo'||!geoMap||!geoReady||!state.plan){closeSwipe();return;}const after=state.plan.recommended;if(state.view!=='recommended'){state.view='recommended';geoMap.getSource('da-network')?.setData(geoFeatures());geoMap.getSource('da-markers')?.setData(geoMarkers());}
 const base=state.baseline,collection={type:'FeatureCollection',features:M.presentation(state.data,base,null).filter(f=>f.geo).map(f=>({type:'Feature',geometry:{type:'LineString',coordinates:f.geo},properties:{id:f.id,status:f.status,selected:false}}))};
 if(!swipeMap){const pane=document.createElement('div');pane.id='before-map';pane.className='map-pane';pane.style.clipPath='inset(0 50% 0 0)';$('geo-map').parentElement.append(pane);const control=document.createElement('div');control.id='swipe-control';control.innerHTML='<label for="swipe-position">Current ← drag → Plan</label><input id="swipe-position" aria-label="Before after swipe position" type="range" min="0" max="100" value="50">';document.querySelector('.stage').append(control);const style=structuredClone(geoMap.getStyle());style.sources['da-network'].data=collection;for(const key of ['da-flood','da-critical'])if(style.sources[key])style.sources[key].data={type:'FeatureCollection',features:[]};const saved=state.view;state.view='current';style.sources['da-markers'].data=geoMarkers();state.view=saved;
  try{swipeMap=new maplibregl.Map({container:'before-map',style,center:geoMap.getCenter(),zoom:geoMap.getZoom(),bearing:geoMap.getBearing(),pitch:geoMap.getPitch(),interactive:false,attributionControl:false});swipeOwner=geoMap;swipeSync=()=>swipeMap?.jumpTo({center:geoMap.getCenter(),zoom:geoMap.getZoom(),bearing:geoMap.getBearing(),pitch:geoMap.getPitch()});geoMap.on('move',swipeSync);swipeMap.on('error',()=>{swipeEnabled=false;closeSwipe();notify('Comparison map unavailable; use Current / Recommended instead.');});$('swipe-position').oninput=e=>{pane.style.clipPath=`inset(0 ${100-Number(e.target.value)}% 0 0)`;};}catch{swipeEnabled=false;closeSwipe();notify('Comparison map unavailable on this device.');}
 }else if(swipeMap.isStyleLoaded()){swipeMap.getSource('da-network')?.setData(collection);swipeMap.resize();}
}
